Theorem push_slow_root_d2_ok : forall (LBo : list (Z * Z)) (FF LK : list fframe) (cr : credit) (A : list (Z * Z)) (sp r V : Z) (es : estate) (b capb : Z) (arr : bool) (ib : Z),
  2 <= depth es ->
  PMSA.cps_asan L ar HI PMES2A.PC_PUSH_SLOW_ROOT_xboth r sp PMES2A.PUSH_SCRA (LBo ++ stack_blocks b capb) FF LK cr A PMES2A.PUSH_DA
    (fun R M => PMSA.a0 R (V + O_STACK) /\ PMES2A.push_argsA L ar M R sp V arr ib /\
                PMESA.stack_at L M V es b capb /\ PMESA.stack_sh M es b capb /\ 32 * depth es = capb /\ depth es < MAX_DEPTH /\
                PMSA.fobj M FF V ENC_SIZE /\ PMSA.stksh ar M sp PMES2A.PUSH_SCRA /\
                acredit_ok L cr (Z.max 32 (2 * capb)) /\ Z.max 32 (2 * capb) <= onmax)
    (fun R M R' M' LB' cr' LBk W => exists (b' capb' : Z),
        PMSA.a0 R' (b' + 32 * depth es + 32) /\ capb' = Z.max 32 (2 * capb) /\
        PMESA.stack_at L M' V (ECtx arr 0 false :: es) b' capb' /\ PMESA.stack_sh M' (ECtx arr 0 false :: es) b' capb' /\
        ablock_range L ar b' capb' /\ blocks_apart b' capb' LBo /\ fframes_apart b' capb' FF /\ L5.defined M' b' capb' /\
